   138	                    $acceptedName = $filename.$resizeNamePattern.'.'.$extension;
   139	                    if ($storageDisk->exists($directory.'/'.$acceptedName)) {
   140	                        $allFiles = collect($storageDisk->allFiles($directory))
   141	                            ->map(fn ($file) => File::basename($file)) // take "filename + extension"
   142	                            ->reject(fn ($item) => $item == "") // reject empty filenames
   143	                            ->sort();
   144	
   145	                        $f = 0;
   146	                        $acceptedName = null;
   147	                        while ($acceptedName === null) {
   148	                            $f++;
   149	                            $newFilename = $filename.'-'.$f.$resizeNamePattern.'.'.$extension;
   150	                            if (!$allFiles->contains($newFilename)) {
   151	                                $acceptedName = $newFilename;
   152	                            }
   153	                        }
   154	
   155	                    }
   156	                    return $acceptedName;
   157	                }
   158	            );
   159	        }
   160	
   161	        /**
   162	         * If using SpatieMediaLibraryFileUpload, always create
   163	         * a collection using the component name
   164	         */
   165	        if ($component instanceof SpatieMediaLibraryFileUpload) {
   166	            $collection = $component->getCollection();
   167	            if (!$collection) {
   168	                $component->collection($component->getName());
   169	            }
   170	        }
   171	
   172	        if ($makeAltText === false) {
   173	            return $component;
   174	        }
   175	
   176	        $name = $component->getName();
   177	
   178	
   179	        /**
   180	         * Build the field to edit the alt text.
   181	         * A column named {$name}_alt_text must exists in the model.
   182	         */
   183	        $altTextInput =  Components\TextInput::make($name.'_alt_text')
   184	            ->label('Testo alternativo');
   185	
   186	        $extraAttributes = ['class' => 'no-border'];
   187	
   188	        $altTextInput = TranslationSection::make('Testo alternativo')
   189	            ->schema([
   190	                $altTextInput
   191	            ])
   192	            ->heading('')
   193	            ->columnSpan(1) // make fit the parent component
   194	        ;
   195	
   196	
   197	        /**
   198	         * Align alt text input if there is no label in the file upload component
   199	         */
   200	        $hasLabel = strlen($component->getLabel()) > 0 || $component->isRequired();
   201	        if ($hasLabel === false) {
   202	            $extraAttributes['style'] = 'margin-top: -2rem;';
   203	        } else {
   204	            $extraAttributes['style'] = 'margin-top: -0.1rem;';
   205	
   206	        }
   207	
   208	        return Components\Grid::make()
   209	            ->columns(2)
   210	            ->schema([
   211	                $component,
   212	                $altTextInput->extraAttributes($extraAttributes),
   213	            ]);
   214	
   215	    }
