   217	    /**
   218	     * Configure the default settings for the FileUpload component
   219	     */
   220	    protected static function internalDefaults(FileUpload $component): FileUpload
   221	    {
   222	
   223	        // if no accepted file types are set, set the default image types
   224	        if (
   225	            $component->getAcceptedFileTypes() === null
   226	        ) {
   227	            $component->image();
   228	        }
   229	
   230	        if ($component->getMaxSize() === null) {
   231	            $component->maxSize(51200); // 50MB
